#!/usr/bin/env python3
"""A patch-stack manager implemented with Git's public plumbing interface."""
import os
import sys
import re
import json
import subprocess
import shlex
import tempfile
import shutil
import time
import datetime
import email.utils
import difflib
import fnmatch
import zipfile
from pathlib import Path
from copy import deepcopy

try:
    HELP = json.loads(Path(__file__).with_name('help.json').read_text())
except (OSError, NotADirectoryError):
    with zipfile.ZipFile(sys.argv[0]) as archive:
        HELP = json.loads(archive.read('help.json'))

VERSION = ('Stacked Git 2.5.5\nCopyright (C) 2005-2025 StGit authors\n'
           'This is free software: you are free to change and redistribute it.\n'
           'There is NO WARRANTY, to the extent permitted by law.\n'
           'SPDX-License-Identifier: GPL-2.0-only\n')
ALIASES = {'add': 'git -C "$GIT_PREFIX" add', 'mv': 'git -C "$GIT_PREFIX" mv',
           'resolved': 'git -C "$GIT_PREFIX" add', 'rm': 'git -C "$GIT_PREFIX" rm',
           'status': 'git status -s'}
COMMANDS = [k[:-3] for k in HELP if k.endswith(' -h') and ' ' not in k[:-3]]
COLOR = False
COMMAND = ''

class StgError(Exception):
    def __init__(self, text, code=2, formatted=False):
        self.text, self.code, self.formatted = text, code, formatted


def out(s):
    sys.stdout.write(str(s))
    sys.stdout.flush()


def err(s):
    sys.stderr.write(str(s))
    sys.stderr.flush()


def fail(s, code=2):
    raise StgError(s, code)


def usage(cmd=None):
    cmd = COMMAND if cmd is None else cmd
    text = HELP.get((cmd + ' -h').strip(), HELP['-h'])
    match = re.search(r'Usage: [^\n]+(?:\n       [^\n]+)*', text)
    return match.group() if match else 'Usage: stg ' + cmd


def cli_error(text, with_usage=True, special_usage=None):
    s = 'error: ' + text + '\n\n'
    if with_usage:
        s += (special_usage or usage()) + '\n\n'
    s += "For more information, try '--help'.\n"
    raise StgError(s, 1, True)


def invalid(value, arg, why=None):
    cli_error("invalid value '%s' for '%s'%s" % (value, arg, ': ' + why if why else ''), False)


def required(what, special=None):
    cli_error('the following required arguments were not provided:\n  ' + what, special_usage=special)


def signature_time():
    now = datetime.datetime.now().astimezone()
    return str(int(now.timestamp())) + ' ' + now.strftime('%z')


def display_date(raw):
    try:
        stamp, zone = raw.split()
        z = datetime.timezone(datetime.timedelta(minutes=(int(zone[1:3])*60+int(zone[3:]))*(1 if zone[0]=='+' else -1)))
        return datetime.datetime.fromtimestamp(int(stamp), z).strftime('%Y-%m-%d %H:%M:%S %z')
    except Exception:
        return raw


def parse_date(value):
    if value == 'now':
        return signature_time()
    if re.fullmatch(r'\d+ [+-]\d{4}', value):
        return value
    v = value
    try:
        if 'T' in value:
            if not re.search(r'[+-]\d\d:\d\d$', value):
                raise ValueError()
            d = datetime.datetime.fromisoformat(value)
        elif re.fullmatch(r'\d{4}-\d\d-\d\d', value):
            d = datetime.datetime.strptime(value, '%Y-%m-%d').replace(tzinfo=datetime.timezone.utc)
        elif re.fullmatch(r'\d{4}-\d\d-\d\d \d\d:\d\d:\d\d [+-]\d{4}', value):
            d = datetime.datetime.strptime(value, '%Y-%m-%d %H:%M:%S %z')
        else:
            d = email.utils.parsedate_to_datetime(value)
        if d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return str(int(d.timestamp())) + ' ' + d.strftime('%z')
    except Exception:
        invalid(v, '--authdate <date>', 'invalid date `%s`' % v)


def patch_name_reason(n):
    if not n:
        return 'patch name may not be empty'
    if '/' in n:
        return "patch name may not contain '/'"
    if any(c.isspace() for c in n):
        return 'patch name may not contain whitespace'
    if '..' in n:
        return "patch name may not contain '..'"
    if n.startswith('.'):
        return "patch name may not start with '.'"
    if n.endswith('.'):
        return "patch name may not end with '.'"
    if n.endswith('.lock'):
        return "patch name may not end with '.lock'"
    if '@{' in n:
        return "patch name may not contain '@{'"
    for c in n:
        if c in '~^:?*[\\' or ord(c) < 32 or ord(c)==127:
            return "patch name may not contain '%s'" % c
    return None


def validate_name(n, arg='[patchname]'):
    n = n[1:] if n.startswith('\\-') else n
    reason = patch_name_reason(n)
    if reason:
        invalid(n, arg, 'invalid patch name `%s`: %s' % (n, reason))
    return n


class Options:
    """Small command line reader preserving the command's public option syntax."""
    def __init__(self, cmd, args):
        self.cmd = cmd
        self.val = {}
        self.pos = []
        self.paths = []
        self.ordered = []
        self.spec = {}
        self.labels = {}
        text = HELP.get(cmd + ' --help', HELP.get(cmd + ' -h',''))
        # Each help option has one declaration line and a stable metavar.
        for line in text.splitlines():
            if not re.match(r'^  (?:-[A-Za-z0-9]|    --)', line):
                continue
            declaration = re.split(r'  +', line.strip(), maxsplit=1)[0]
            # Long help has no descriptive text on the declaration line.
            opts = re.findall(r'(?<!\w)(--[\w-]+|-[A-Za-z0-9])', declaration)
            if not opts:
                continue
            key = next((x[2:] for x in opts if x.startswith('--')), opts[0][1:])
            optional = '[=' in declaration
            hasvalue = '<' in declaration or optional
            longopt = next((x for x in opts if x.startswith('--')), opts[0])
            suffix = declaration[declaration.find(longopt)+len(longopt):]
            suffix = re.split(r',|  +', suffix)[0]
            label = longopt + (suffix if hasvalue else '')
            for opt in opts:
                self.spec[opt] = (key, 2 if optional else 1 if hasvalue else 0)
            self.labels[key] = label
        self.spec.update({'--color':('color',1),'-h':('help',0),'--help':('help',0)})
        self.labels['color'] = '--color <when>'
        if cmd=='branch':
            for opt,k in [('--list','list'),('-l','list'),('--create','create'),('-c','create'),('--clone','clone'),('-C','clone'),('--rename','rename'),('-r','rename'),('--protect','protect'),('-p','protect'),('--unprotect','unprotect'),('-u','unprotect'),('--delete','delete'),('-D','delete'),('--cleanup','cleanup')]:
                self.spec[opt]=(k,0);self.labels[k]=next((a for a,b in [(opt,k)]),opt)
            self.spec.update({'--force':('force',0),'--describe':('describe',1),'-d':('describe',1)})
            self.labels['describe']='--describe <description>'
        if cmd=='sink':
            self.spec['--to']=('below',1)
        if cmd=='version':
            self.spec['--short']=('short',0)
        repeat = {'signoff','ack','review','diff-opt','git-opt','patch' if cmd=='show' else '_','file' if cmd=='pick' else '_','to' if cmd.startswith('email') else '_','cc','add-header'}
        consume_after = cmd in {'series','hide','unhide','delete','float','sink','squash','export','uncommit','sync','pick','log','rename'}
        accept_hyphen = cmd in {'series','id','name','files','rename','hide','unhide','delete','float','sink','squash','export','uncommit','sync','pick','log'}
        i = 0
        end = False
        while i < len(args):
            a = args[i]
            if a=='--' and not end:
                if cmd in {'new','show'}:
                    self.paths = args[i+1:];break
                end = True;i+=1;continue
            if end or (consume_after and self.pos):
                self.pos.append(a);i+=1;continue
            keyarg,eq,v=a.partition('=')
            pieces=[]
            if keyarg in self.spec:
                pieces=[(keyarg,v if eq else None)]
            elif a.startswith('-') and not a.startswith('--') and len(a)>2:
                j=1
                while j<len(a):
                    short='-'+a[j]
                    if short not in self.spec:
                        pieces=[];break
                    key,mode=self.spec[short]
                    if mode==1:
                        pieces.append((short,a[j+1:] or None));break
                    if mode==2 and j+1<len(a):
                        pieces=[];break
                    pieces.append((short,None));j+=1
            if not pieces:
                if a.startswith('-') and a!='-' and not accept_hyphen and not re.match(r'^-\d+$',a) and not a.startswith('\\-'):
                    text="unexpected argument '%s' found" % a
                    candidates=difflib.get_close_matches(a,[x for x in self.spec if x.startswith('--')],n=1,cutoff=.78)
                    text+='\n'
                    if candidates:
                        text+="\n  tip: a similar argument exists: '%s'" % candidates[0]
                    text+="\n  tip: to pass '%s' as a value, use '-- %s'" % (a,a)
                    cli_error(text)
                self.pos.append(a);i+=1;continue
            for opt,val in pieces:
                k,mode=self.spec[opt]
                label=self.labels.get(k,opt)
                if mode==1 and val is None:
                    i+=1
                    if i>=len(args):
                        cli_error("a value is required for '%s' but none was supplied" % label, False)
                    val=args[i]
                elif mode==2 and val is None:
                    val={'short':'5','commit-id':'full','conflicts':'allow','thread':'shallow'}.get(k,True)
                elif mode==0:
                    if val is not None:
                        cli_error("unexpected value '%s' for '%s' found; no more were expected" % (val,label))
                    val=True
                if val=='' and mode==1:
                    cli_error("a value is required for '%s' but none was supplied" % label,False)
                if k in self.val and k not in repeat:
                    cli_error("the argument '%s' cannot be used multiple times" % label)
                self.ordered.append(k)
                if k in repeat:
                    self.val.setdefault(k,[]).append(val)
                else:
                    self.val[k]=val
            i+=1
        for k in ('authdate',):
            if k in self.val:
                self.val[k]=parse_date(self.val[k])
        if 'author' in self.val and cmd in {'new','edit','refresh','import','squash'}:
            if not re.fullmatch(r'.*?\s*<[^<>]*>',self.val['author']):
                invalid(self.val['author'],'--author <name-and-email>','invalid name and email `%s`'%self.val['author'])
        if 'color' in self.val and self.val['color'] not in {'auto','always','ansi','never'}:
            cli_error("invalid value '%s' for '--color <when>'\n  [possible values: auto, always, ansi, never]"%self.val['color'],False)
        if 'commit-id' in self.val:
            v=self.val['commit-id']
            if v!='full' and (not v.isdigit() or int(v)<4):
                invalid(v,'--commit-id[=<length>]','length must be "full" or an integer greater than or equal to 4')
        for k in ['number','short' if cmd=='series' else '_','strip','C','start-number']:
            if k in self.val and type(self.val[k]) is str:
                v=self.val[k]
                try:self.val[k]=int(v)
                except ValueError:invalid(v,self.labels.get(k,'--'+k),'invalid digit found in string')
                if k=='number' and cmd in {'uncommit','commit','undo','redo','log'} and self.val[k]<0:
                    invalid(v,self.labels.get(k,'--'+k),"'%s' is not a positive integer"%v)
        if cmd in {'new','squash'}:
            if cmd=='new' and self.pos:
                self.pos[0]=validate_name(self.pos[0])
            if 'name' in self.val:
                self.val['name']=validate_name(self.val['name'],'--name <name>')
        conflicts=[('message','file'),('message','save-template'),('file','save-template'),('index','force')]
        if cmd in {'series','delete'}:
            conflicts += [('applied','all'),('unapplied','all'),('hidden','all')]
        if cmd in {'push','pop','commit'}:
            conflicts += [('all','number')]
        for a,b in conflicts:
            if a in self.val and b in self.val:
                if self.ordered.index(b)<self.ordered.index(a):a,b=b,a
                cli_error("the argument '%s' cannot be used with '%s'"%(self.labels.get(a,'--'+a),self.labels.get(b,'--'+b)))
        self.validate_required()

    def validate_required(self):
        cmd=self.cmd
        if cmd in {'hide','unhide','squash','goto','pick'} and not self.pos:
            item='<patch>' if cmd=='goto' else '<source>...' if cmd=='pick' else '<patch>...'
            required(item,'Usage: stg '+cmd+' '+item if cmd in {'goto','hide','unhide','squash'} else None)
        if cmd=='rename' and not self.pos:required('<patches>...')
        if cmd=='float' and not self.pos and not self.get('series'):required('<patch>...')
        if cmd=='delete' and not self.pos and not any(self.get(x) for x in ['all','applied','unapplied','hidden','top']):required('<patch>...')
        if cmd=='reset' and not self.pos and not self.get('hard'):required('<committish>')
        limits={'new':1,'id':1,'name':1,'files':1,'edit':1,'goto':1,'top':0,'prev':0,'next':0,'init':0,'clean':0,'undo':0,'redo':0,'repair':0,'version':0,'import':1,'fold':1,'rebase':1,'pull':1,'rename':2}
        if cmd in limits and len(self.pos)>limits[cmd]:
            cli_error("unexpected argument '%s' found"%self.pos[limits[cmd]])

    def get(self,k,default=None):return self.val.get(k,default)
    def __contains__(self,k):return k in self.val


class Git:
    def __init__(self):
        self.cwd=os.getcwd()
        p=self.run('rev-parse','--absolute-git-dir',check=False)
        if p.returncode:
            fail("Could not find a git repository in '.' or in any of its parents")
        self.dir=p.stdout.strip()
        p=self.run('rev-parse','--show-toplevel',check=False)
        self.root=p.stdout.strip() if not p.returncode else self.cwd
        self.prefix=os.path.relpath(self.cwd,self.root)
        if self.prefix=='.':self.prefix=''
        self.cache={}

    def run(self,*args,input=None,check=True,env=None,cwd=None):
        e=os.environ.copy();e['GIT_PAGER']='cat';e['GIT_TERMINAL_PROMPT']='0'
        if env:e.update(env)
        p=subprocess.run(['git',*map(str,args)],cwd=cwd or self.cwd,env=e,input=input,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,errors='surrogateescape')
        if check and p.returncode:
            s=p.stderr.strip()
            s=re.sub(r'^(fatal|error): ','',s)
            fail(s or 'git command failed')
        return p

    def text(self,*args,**kw):return self.run(*args,**kw).stdout.strip()
    def raw(self,*args,**kw):return self.run(*args,**kw).stdout
    def config(self,k,default=None):
        p=self.run('config','--get',k,check=False)
        return p.stdout.rstrip('\n') if not p.returncode else default
    def rev(self,rev):
        p=self.run('rev-parse','--verify',str(rev)+'^{commit}',check=False)
        return p.stdout.strip() if not p.returncode else None
    def commit(self,oid):
        if oid in self.cache:return self.cache[oid]
        raw=self.raw('cat-file','commit',oid)
        hdr,_,msg=raw.partition('\n\n')
        d={'oid':oid,'parents':[],'message':msg}
        for line in hdr.splitlines():
            k,_,v=line.partition(' ')
            if k=='parent':d['parents'].append(v)
            elif k in ('tree','author','committer'):d[k]=v
        d['subject']=' '.join(msg.strip().split('\n\n')[0].splitlines()).strip() if msg.strip() else ''
        self.cache[oid]=d
        return d
    def tree(self,oid):return self.commit(oid)['tree']
    def identity(self,kind='committer'):
        env='GIT_'+kind.upper()+'_'
        name=os.environ.get(env+'NAME') or self.config('user.name')
        email_=os.environ.get(env+'EMAIL') or self.config('user.email') or os.environ.get('EMAIL')
        if not name or not email_:
            label='author' if kind=='author' else 'committer'
            fail('unable to determine '+label+' name and email')
        return name.strip()+' <'+email_.strip()+'>'
    def write(self,kind,data):return self.text('hash-object','-t',kind,'-w','--stdin',input=data)
    def make_commit(self,tree,parents,msg,author=None,committer=None):
        sig=self.identity()+' '+signature_time()
        data='tree '+tree+'\n'+''.join('parent '+p+'\n' for p in parents)
        data+='author '+(author or sig)+'\ncommitter '+(committer or sig)+'\n\n'+msg
        return self.write('commit',data)
    def dirty(self):
        index=bool(self.text('diff','--cached','--name-only'))
        work=bool(self.text('diff','--name-only'))
        return index,work
    def check_clean(self):
        index,work=self.dirty()
        if index:fail('index not clean; use `refresh` or `reset --hard`')
        if work:fail('worktree not clean; use `refresh` or `reset --hard`')
    def reset_tree(self,old,new,keep=False,hard=False):
        if hard:
            self.run('read-tree','--reset','-u',new)
        elif old!=new:
            self.run('read-tree','-m','-u',old,new)
    def changed_files(self,a,b,paths=None):
        return self.raw('diff','--name-only',a,b,'--',*(paths or [])).splitlines()


class Stack:
    def __init__(self,g,branch=None,required=False):
        self.g=g
        current=g.text('symbolic-ref','--quiet','--short','HEAD',check=False)
        self.branch=branch or current
        if not self.branch:fail('not on branch, HEAD is detached')
        if self.branch.startswith('refs/heads/'):self.branch=self.branch[11:]
        self.branchref='refs/heads/'+self.branch
        self.head=g.rev(self.branchref)
        if not self.head:
            if branch:fail('branch `%s` not found'%branch)
            fail('branch `%s` is unborn'%self.branchref)
        self.current=self.branch==current
