def patch_name_reason(n):
    if not n:
        return 'patch name may not be empty'
    if '/' in n:
        return "patch name may not contain '/'"
    if any(c.isspace() for c in n):
        return 'patch name may not contain whitespace'
    if '..' in n:
        return "patch name may not contain '..'"
    if n.startswith('.'):
