                    if val:stamp=parse_date(val);author=author.rsplit(' ',2)[0]+' '+stamp
                elif not line:headers=False
                else:headers=False;body.append(line)
            else:body.append(line)
        msg=g.raw('stripspace',input='\n'.join(body))
    for k,label in [('signoff','Signed-off-by'),('ack','Acked-by'),('review','Reviewed-by')]:
        vals=opts.get(k,[])
        if k=='signoff' and not vals and g.config('stgit.autosign','false').lower() in {'true','yes','1'}:vals=[True]
        for value in vals:
