def capture_refresh_tree(s,opts,paths=None,patch=None):
    g=s.g
    index_dirty,work_dirty=g.dirty()
    if index_dirty and work_dirty and not opts.get('index') and not opts.get('force'):
        fail('the index is dirty; consider using `--index` or `--force`')
    paths=paths or []
    update=opts.get('update')
    if not paths and not update:
        if not opts.get('index'):g.run('add','-u',cwd=g.root)
        return g.text('write-tree')
    selected=set(g.raw('ls-files','--',*paths).splitlines()) if paths else set(g.raw('ls-files').splitlines())
    # Convert relative paths to root-relative entries for index operations.
    if g.prefix:selected={g.prefix+'/'+x for x in selected}
    if update:
        c=g.commit(s.patches[patch or s.top()]);changed=set(g.changed_files(c['parents'][0],c['oid']))
        if g.prefix:changed={g.prefix+'/'+x for x in changed}
        selected &= changed
    tmp,env=temp_index(g,s.topid())
    try:
        entries={}
        for line in g.raw('ls-files','--stage',cwd=g.root).splitlines():
            part,_,name=line.partition('\t');vals=part.split()
            if len(vals)==3 and vals[2]=='0':entries[name]=(vals[0],vals[1])
        for f in selected:
            if f in entries:
                mode,oid=entries[f];g.run('update-index','--add','--cacheinfo',mode,oid,f,env=env,cwd=g.root)
            else:g.run('update-index','--force-remove','--',f,env=env,cwd=g.root)
        if not opts.get('index') and selected:g.run('add','-u','--',*sorted(selected),env=env,cwd=g.root)
        tree=g.text('write-tree',env=env)
        if not opts.get('index') and selected:
            g.run('add','-u','--',*sorted(selected),cwd=g.root)
        return tree
    finally:
        try:os.unlink(tmp)
        except OSError:pass


def command_new(s,o):
    s.check_head()
    name=o.get('name') or (o.pos[0] if o.pos else None)
    if name in s.patches:fail('patch `%s` already exists'%name)
    msg,author,name=prepare_message(s,o,name,editor=True)
    if msg is None:return
    if name is None:name=s.make_name(msg)
    name=validate_name(name)
    if name in s.patches:fail('patch `%s` already exists'%name)
    s.ensure()
    tree=capture_refresh_tree(s,o,o.paths) if o.get('refresh') or o.get('index') or o.paths else s.g.tree(s.topid())
    stamp=' '.join(author.rsplit(' ',2)[-2:]) if o.get('committer-date-is-author-date') else signature_time()
    oid=s.g.make_commit(tree,[s.topid()],msg,author,s.g.identity()+' '+stamp)
    s.patches[name]=oid;s.applied.append(name)
    set_head(s,oid)
    status('>',name,' (new)')
    s.save('new: '+name)


def command_refresh(s,o):
    n=s.select_one(o.get('patch')) if o.get('patch') else s.top()
    if n not in s.applied:fail('patch `%s` is not applied'%n)
    s.check_head();s.ensure()
    msg,author,_=prepare_message(s,o,n,s.g.commit(s.patches[n]),editor=False)
    tree=capture_refresh_tree(s,o,o.pos,n)
    base=s.topid()
    temp='refresh-temp';num=1
    while temp in s.patches:temp='refresh-temp-'+str(num);num+=1
    oid=s.g.make_commit(tree,[base],'Refresh of '+n+'\n',s.g.identity('author')+' '+signature_time())
    s.patches[temp]=oid;s.applied.append(temp);set_head(s,oid)
    status('>',temp,' (new)')
    s.save('refresh '+temp+' (create temporary patch)')
    idx=s.applied.index(n);above=s.applied[idx+1:-1]
    if above:
        pop_to(s,idx+1)
        push_one(s,temp,o,True)
        tree=s.g.tree(s.patches[temp])
    group_status('-',[temp])
    s.applied.remove(temp);s.unapplied=[x for x in s.unapplied if x!=temp];del s.patches[temp]
    group_status('#',[temp])
    new,changed=change_patch_commit(s,n,tree,msg,author,o)
    if changed:status('&',n)
    set_head(s,new)
    if above:push_many(s,above,o)
    else:final_top(s)
