    s.save('refresh '+n+(' ('+note+')' if note else ''))


def command_edit(s,o):
    n=s.select_one(o.pos[0]) if o.pos else s.top();s.check_head()
    c=s.g.commit(s.patches[n])
    do_editor=not any(o.get(k) for k in ['message','file','author','authname','authemail','authdate','signoff','ack','review','set-tree'])
    msg,author,_=prepare_message(s,o,n,c,editor=do_editor)
    if msg is None:return
