def command_push_pop(s,o,push=False):
    s.check_head()
    available=s.unapplied if push else s.applied
    if 'number' in o and o.get('number')==0:return
    if not available:fail('no unapplied patches' if push else 'no patches applied')
    if o.pos:selected=s.ranges(o.pos,'unapplied' if push else 'applied')
    elif o.get('all'):selected=available[:]
    elif 'number' in o:
        n=o.get('number');n=min(n,len(available)) if n>=0 else max(0,len(available)+n)
        selected=available[:n] if push else available[len(available)-n:]
    else:selected=[available[0] if push else available[-1]]
    if not selected:return
    if not o.get('keep') and not o.get('spill'):s.g.check_clean()
    if push:
        if o.get('reverse'):selected.reverse()
        if o.get('noapply'):
            s.unapplied=selected+[n for n in s.unapplied if n not in selected]
            for n in selected:status('-',n)
            final_top(s)
        else:push_many(s,selected,o)
        s.save('push')
    else:
        first=min(s.applied.index(n) for n in selected)
        tail=s.applied[first:]
        pop_to(s,first,spill=o.get('spill'),keep=o.get('keep'))
        remaining=[n for n in tail if n not in selected]
        if remaining:push_many(s,remaining,o)
        else:final_top(s)
        s.save('pop')


def delete_selected(s,o,selected,message='delete'):
    if not selected:return
    orig=s.all();tail=[]
    ap=[n for n in selected if n in s.applied]
    if ap:
        if not o.get('spill'):s.g.check_clean()
        i=min(s.applied.index(n) for n in ap);tail=s.applied[i:]
        pop_to(s,i,spill=o.get('spill'))
    group=[]
    for n in orig+[None]:
        if n in selected:group.append(n)
        elif group:group_status('#',group);group=[]
    for n in selected:
        s.applied=[x for x in s.applied if x!=n]
        s.unapplied=[x for x in s.unapplied if x!=n]
        s.hidden=[x for x in s.hidden if x!=n]
        del s.patches[n]
    remaining=[n for n in tail if n not in selected]
    if remaining:push_many(s,remaining,o)
    else:final_top(s)
    s.save(message)


def command_delete_clean(s,o,clean=False):
    s.check_head()
    if clean:
        pool=(s.applied if not o.get('unapplied') or o.get('applied') else [])+(s.unapplied if not o.get('applied') or o.get('unapplied') else [])
        selected=[n for n in pool if s.is_empty(n)]
    elif o.pos:selected=s.ranges(o.pos)
    elif o.get('top'):selected=[s.top()]
    elif o.get('all'):selected=s.all()
    else:selected=(s.applied if o.get('applied') else [])+(s.unapplied if o.get('unapplied') else [])+(s.hidden if o.get('hidden') else [])
    delete_selected(s,o,selected,'clean' if clean else 'delete')


def command_hide(s,o,unhide=False):
    s.check_head()
    selected=s.ranges(o.pos,'hidden' if unhide else 'all')
    if unhide:
        for n in selected:
            s.hidden.remove(n);s.unapplied.append(n);status('-',n)
        final_top(s);s.save('unhide');return
    selected=[n for n in selected if n not in s.hidden]
    if not selected:return
    ap=[n for n in selected if n in s.applied];above=[]
    if ap:
        s.g.check_clean();i=min(s.applied.index(n) for n in ap);tail=s.applied[i:]
        pop_to(s,i);above=[n for n in tail if n not in selected]
    if above:push_many(s,above,o)
    else:final_top(s)
