def command_rename(s,o):
    s.check_head()
    if len(o.pos)==1:old=s.top();new=o.pos[0]
    else:old=s.select_one(o.pos[0]);new=o.pos[1]
    new=validate_name(new,'<patches>...')
    if new in s.patches:fail('patch `%s` already exists'%new)
    s.patches[new]=s.patches.pop(old)
    for group in [s.applied,s.unapplied,s.hidden]:
        if old in group:group[group.index(old)]=new
    if COLOR:out('\x1b[0m\x1b[2m'+old+'\x1b[0m\x1b[34m => \x1b[0m'+new+'\n')
    else:out(old+' => '+new+'\n')
    final_top(s);s.save('rename '+old+' => '+new)


def command_goto(s,o):
    s.check_head();n=s.ranges(o.pos,'visible')[0]
    if not o.get('keep'):s.g.check_clean()
    if n in s.applied:
        pop_to(s,s.applied.index(n)+1,keep=o.get('keep'));final_top(s)
    else:push_many(s,s.unapplied[:s.unapplied.index(n)+1],o)
    s.save('goto '+n)


def reorder(s,o,applied,unapplied,message):
    common=0
    while common<min(len(s.applied),len(applied)) and s.applied[common]==applied[common]:common+=1
    if common<len(s.applied):pop_to(s,common,keep=o.get('keep'))
    todo=applied[common:]
    if todo:push_many(s,todo,o)
    else:final_top(s)
    s.unapplied=unapplied
    s.save(message)


def command_float_sink(s,o,sink=False):
    s.check_head()
    if not o.get('keep'):s.g.check_clean()
    args=o.pos
    if o.get('series'):
        try:args=[l.split('#',1)[0].strip() for l in Path(o.get('series')).read_text().splitlines()];args=[a for a in args if a]
        except OSError:fail('No such file or directory (os error 2)')
    selected=s.ranges(args,'visible') if args else [s.top()]
    allvis=s.applied+s.unapplied
    if sink:
        remaining=[n for n in allvis if n not in selected]
        target=o.get('below') or o.get('above')
        if target:
            target=s.select_one(target)
            if target in selected:fail('target patch `%s` is also selected'%target)
            if target not in remaining:fail('hidden patch `%s` is not allowed'%target)
            i=remaining.index(target)+(1 if o.get('above') else 0)
        else:i=0
        ordered=remaining[:i]+selected+remaining[i:]
        applied_count=len(s.applied)+len([x for x in selected if x in s.unapplied])
        if o.get('nopush'):
            applied_count=0
            while applied_count<min(i,len(s.applied)) and s.applied[applied_count]==ordered[applied_count]:applied_count+=1
        desired=ordered[:applied_count];unap=ordered[applied_count:]
    elif o.get('noapply'):
        desired=[n for n in s.applied if n not in selected]
        unap=selected+[n for n in s.unapplied if n not in selected]
    else:
        desired=[n for n in s.applied if n not in selected]+selected
        unap=[n for n in s.unapplied if n not in selected]
    reorder(s,o,desired,unap,'sink' if sink else 'float')
