def status(symbol,name,suffix='',final=False):
    if not COLOR:
        out(symbol+' '+name+suffix+'\n');return
    colors={'>':'34','+':'32','-':'35','!':'31','#':'33','$':'33','&':'36'}
    style='1' if symbol=='>' else '2' if symbol in '-#!$' else '0'
    out('\x1b[0m\x1b['+colors.get(symbol,'34')+'m'+symbol+' \x1b[0m\x1b['+style+'m'+name)
    if final and not suffix:out('\n\x1b[0m')
    else:
        out('\x1b[0m')
        if suffix:out('\x1b[0m\x1b[33m'+suffix+'\n\x1b[0m')
        else:out('\n')


def group_status(symbol,names):
    if names:status(symbol,names[0] if len(names)==1 else names[0]+'..'+names[-1])


def final_top(s):
    if s.applied:status('>',s.applied[-1],final=True)


def set_head(s,new,checkout=False,keep=False,hard=False):
    old=s.head
    if checkout and s.current:s.g.reset_tree(old,new,keep,hard)
    if new!=old:s.g.run('update-ref',s.branchref,new)
    s.head=new


def pop_to(s,index,spill=False,keep=False):
    popped=s.applied[index:]
    if not popped:return []
    group_status('-',popped)
    s.applied=s.applied[:index]
    s.unapplied=popped+[n for n in s.unapplied if n not in popped]
    set_head(s,s.topid(),checkout=not spill,keep=keep)
    return popped


def temp_index(g,tree):
    fd,path=tempfile.mkstemp(prefix='stg-index-',dir=g.dir);os.close(fd);os.unlink(path)
    env={'GIT_INDEX_FILE':path}
    g.run('read-tree',tree,env=env)
    return path,env


def patch_apply_tree(s,oid,base,reverse=False):
    g=s.g;c=g.commit(oid)
    if not c['parents']:fail('commit `%s` does not have a parent'%oid)
    parent=c['parents'][0]
    if not reverse and g.tree(parent)==g.tree(base):return c['tree'],None
    if reverse and g.tree(oid)==g.tree(base):return g.tree(parent),None
    diff=g.raw('diff','--binary',parent,oid)
    if not diff:return g.tree(base),None
    index,env=temp_index(g,base)
    try:
        args=['apply','--cached','--3way']
        if reverse:args.append('-R')
        p=g.run(*args,input=diff,env=env,check=False,cwd=g.root)
        if p.returncode:
            return None,(p.stderr,index,env,diff)
        tree=g.text('write-tree',env=env)
        return tree,None
    finally:
        if 'p' in locals() and not p.returncode:
            try:os.unlink(index)
            except OSError:pass


def push_one(s,n,opts,last=False,emit=True,set_tree=False):
    g=s.g;oid=s.patches[n];c=g.commit(oid);base=s.topid()
    same=bool(c['parents'] and c['parents'][0]==base)
    suffix=''
    if same and not opts.get('merged'):
        new=oid
    else:
        if set_tree or opts.get('set-tree'):tree=c['tree'];conflict=None
        else:tree,conflict=patch_apply_tree(s,oid,base)
        if conflict:
            stderr,index,env,diff=conflict
            allow=opts.get('conflicts',g.config('stgit.push.allow-conflicts','true')) not in {'disallow','false','no'}
            if not allow:
                try:os.unlink(index)
                except OSError:pass
                fail('patch `%s` does not apply cleanly'%n)
            unmerged=g.raw('ls-files','-u',env=env)
            files=[]
            for line in unmerged.splitlines():
                if '\t' in line:
                    f=line.split('\t',1)[1]
                    if f not in files:files.append(f)
            if not files:
                try:os.unlink(index)
                except OSError:pass
                fail(stderr.strip() or 'patch does not apply')
            if s.current:
                shutil.copyfile(index,os.path.join(g.dir,'index'))
                g.run('checkout','--conflict=merge','--',*files,check=False,cwd=g.root)
            for f in files:out('CONFLICT (content): Merge conflict in '+f+'\n')
            new=g.make_commit(g.tree(base),[base],c['message'],c['author'])
            s.patches[n]=new
            s.unapplied=[x for x in s.unapplied if x!=n];s.applied.append(n)
            set_head(s,new)
            status('>',n,' (conflict)')
            s.save('push (conflict)')
            try:os.unlink(index)
            except OSError:pass
            fail('%d merge conflict%s'%(len(files),'' if len(files)==1 else 's'),3)
        if tree==g.tree(base):suffix=' (empty)'
        date=c['author'].rsplit(' ',2)[-2:]
        committer=g.identity()+' '+(' '.join(date) if opts.get('committer-date-is-author-date') else signature_time())
        new=g.make_commit(tree,[base],c['message'],c['author'],committer)
    s.patches[n]=new
    s.unapplied=[x for x in s.unapplied if x!=n]
    s.hidden=[x for x in s.hidden if x!=n]
    s.applied.append(n)
    set_head(s,new,checkout=True,keep=opts.get('keep'))
    if emit:status('>' if last else '+',n,suffix)


def push_many(s,names,opts):
    for i,n in enumerate(names):push_one(s,n,opts,i==len(names)-1)


def change_patch_commit(s,n,tree,msg,author,opts):
    g=s.g;c=g.commit(s.patches[n])
    if tree==c['tree'] and msg==c['message'] and author==c['author']:
        return s.patches[n],False
    ad=' '.join(author.rsplit(' ',2)[-2:])
    com=g.identity()+' '+(ad if opts.get('committer-date-is-author-date') else signature_time())
    oid=g.make_commit(tree,c['parents'],msg,author,com)
    s.patches[n]=oid
    return oid,True


def message_template(name,author,message):
    ident,stamp=author.rsplit(' ',2)[0], ' '.join(author.rsplit(' ',2)[-2:])
    return ('Patch:  '+(name or '')+'\nAuthor: '+ident+'\nDate:   '+display_date(stamp)+'\n\n'+message.rstrip('\n')+
            "\n\n\n# Please enter the message for your patch. Lines starting with\n"
            "# '#' will be ignored. An empty message aborts the new patch.\n"
            "# The patch name and author information may also be modified.\n")


def prepare_message(s,opts,name=None,old=None,default='',editor=False):
    g=s.g
    author=old['author'] if old else g.identity('author')+' '+signature_time()
    ident,stamp=author.rsplit(' ',2)[0], ' '.join(author.rsplit(' ',2)[-2:])
    m=re.fullmatch(r'(.*) <(.*)>',ident)
    an,ae=m.groups() if m else (ident,'')
    if opts.get('author'):
        an,ae=re.fullmatch(r'(.*?)\s*<([^<>]*)>',opts.get('author')).groups();an=an.strip()
    an=opts.get('authname',an);ae=opts.get('authemail',ae)
    stamp=opts.get('authdate',stamp)
    author=an+' <'+ae+'> '+stamp
    msg=old['message'] if old else default
    if opts.get('message') is not None:
        msg=opts.get('message')
    elif opts.get('file') is not None:
        filename=opts.get('file')
        try:msg=sys.stdin.read() if filename=='-' else Path(filename).read_text(errors='surrogateescape')
        except OSError as e:fail('No such file or directory (os error 2)' if e.errno==2 else str(e))
    msg=g.raw('stripspace',input=msg)
    if opts.get('save-template') is not None:
        text=message_template(name,author,msg)
        dest=opts.get('save-template')
        if dest=='-':out(text)
