def capture_refresh_tree(s,opts,paths=None,patch=None):
    g=s.g
    index_dirty,work_dirty=g.dirty()
    if index_dirty and work_dirty and not opts.get('index') and not opts.get('force'):
        fail('the index is dirty; consider using `--index` or `--force`')
    paths=paths or []
    update=opts.get('update')
    if not paths and not update:
        if not opts.get('index'):g.run('add','-u',cwd=g.root)
        return g.text('write-tree')
    selected=set(g.raw('ls-files','--',*paths).splitlines()) if paths else set(g.raw('ls-files').splitlines())
    # Convert relative paths to root-relative entries for index operations.
    if g.prefix:selected={g.prefix+'/'+x for x in selected}
    if update:
        c=g.commit(s.patches[patch or s.top()]);changed=set(g.changed_files(c['parents'][0],c['oid']))
        if g.prefix:changed={g.prefix+'/'+x for x in changed}
        selected &= changed
    tmp,env=temp_index(g,s.topid())
    try:
        entries={}
        for line in g.raw('ls-files','--stage',cwd=g.root).splitlines():
            part,_,name=line.partition('\t');vals=part.split()
            if len(vals)==3 and vals[2]=='0':entries[name]=(vals[0],vals[1])
        for f in selected:
            if f in entries:
                mode,oid=entries[f];g.run('update-index','--add','--cacheinfo',mode,oid,f,env=env,cwd=g.root)
            else:g.run('update-index','--force-remove','--',f,env=env,cwd=g.root)
        if not opts.get('index') and selected:g.run('add','-u','--',*sorted(selected),env=env,cwd=g.root)
        tree=g.text('write-tree',env=env)
        if not opts.get('index') and selected:
            g.run('add','-u','--',*sorted(selected),cwd=g.root)
        return tree
    finally:
        try:os.unlink(tmp)
        except OSError:pass


