def command_push_pop(s,o,push=False):
    s.check_head()
    available=s.unapplied if push else s.applied
    if 'number' in o and o.get('number')==0:return
    if not available:fail('no unapplied patches' if push else 'no patches applied')
    if o.pos:selected=s.ranges(o.pos,'unapplied' if push else 'applied')
    elif o.get('all'):selected=available[:]
    elif 'number' in o:
        n=o.get('number');n=min(n,len(available)) if n>=0 else max(0,len(available)+n)
        selected=available[:n] if push else available[len(available)-n:]
    else:selected=[available[0] if push else available[-1]]
    if not selected:return
    if not o.get('keep') and not o.get('spill'):s.g.check_clean()
    if push:
        if o.get('reverse'):selected.reverse()
        if o.get('noapply'):
            s.unapplied=selected+[n for n in s.unapplied if n not in selected]
            for n in selected:status('-',n)
            final_top(s)
        else:push_many(s,selected,o)
        s.save('push')
    else:
        first=min(s.applied.index(n) for n in selected)
        tail=s.applied[first:]
        pop_to(s,first,spill=o.get('spill'),keep=o.get('keep'))
        remaining=[n for n in tail if n not in selected]
        if remaining:push_many(s,remaining,o)
        else:final_top(s)
        s.save('pop')


