def reconstruct_history(s):
    chain=[];rev=s.oldref
    while rev:
        state=s.read_state(rev)
        chain.append((rev,state,s.g.commit(rev)['message']))
        rev=state.get('prev')
        if len(chain)>1000:break
    undo=[];redo=[];previous=None
    for rev,state,msg in reversed(chain):
