def split_patch_data(g,data,is_mail=False):
    meta={}
    if is_mail or re.match(r'^(From [0-9a-f]+ |From:|Subject:|Date:)',data):
        with tempfile.TemporaryDirectory(prefix='stg-mail-',dir=g.dir) as d:
            msgf=os.path.join(d,'msg');patchf=os.path.join(d,'patch')
            p=g.run('mailinfo',msgf,patchf,input=data,check=False)
            if not p.returncode:
                for line in p.stdout.splitlines():
                    k,_,v=line.partition(': ');meta[k.lower()]=v
                msg=Path(msgf).read_text(errors='surrogateescape')
                diff=Path(patchf).read_text(errors='surrogateescape')
                subj=meta.get('subject','')
                return subj+('\n\n'+msg if msg.strip() else '\n'),diff,meta
    lines=data.splitlines(True);start=None
    for i,line in enumerate(lines):
        if line.startswith('diff --git ') or (line.startswith('--- ') and i+1<len(lines) and lines[i+1].startswith('+++ ')):
            start=i;break
    if start is None:
        return data,'',meta
    header=''.join(lines[:start]);diff=''.join(lines[start:])
    if '\n---\n' in header:header=header.split('\n---\n',1)[0]
    result=[]
    for line in header.splitlines():
        if line.startswith('From: '):
            m=re.match(r'(.*) <(.*)>',line[6:])
            if m:meta['author'],meta['email']=m.groups()
        elif line.startswith('Date: '):meta['date']=line[6:]
