    skip={'all','branch','color','git-opt'}
    for k,v in o.val.items():
        if k in skip:continue
        values=v if isinstance(v,list) else [v]
        for value in values:
            if value is True:args.append('--'+k)
            else:args.append('--'+k+'='+str(value))
    for value in o.get('git-opt',[]):args+=shlex.split(value)
    # format-patch accepts a revision set; exclusions preserve arbitrary selections.
    args += [s.patches[n] for n in patches]
    for n in patches:
        c=g.commit(s.patches[n])
        if c['parents'] and c['parents'][0] not in [s.patches[x] for x in patches]:args.append('^'+c['parents'][0])
    p=g.run(*args,check=False)
    out(p.stdout);err(p.stderr)
    if p.returncode:raise StgError('',p.returncode,True)


def configured_aliases():
    result=ALIASES.copy()
    p=subprocess.run(['git','config','--get-regexp',r'^stgit\.alias\.'],capture_output=True,text=True)
    for line in p.stdout.splitlines():
        key,_,val=line.partition(' ');name=key[len('stgit.alias.'):]
        result[name]=val
    return result


def command_completion(cmd,o,aliases):
    style=o.get('style','name-only')
    which=cmd.split()[-1]
    if which not in {'commands','aliases','commands-and-aliases'}:
        if cmd=='completion':required('<COMMAND>')
        fail('completion output is not available for this shell')
    commands=sorted(c for c in COMMANDS if c!='help')+['help']
    entries=[]
    if which!='aliases':
        for c in commands:
            desc=HELP.get(c+' -h','Print this message or the help of the given subcommand(s)').splitlines()[0]
            entries.append((c,desc))
    if which!='commands':
        for a,exp in sorted(aliases.items()):
            shell=not exp or exp.startswith('!') or a in ALIASES
            entries.append((a,'Alias for '+('shell command' if shell else 'StGit command')+' `'+exp.lstrip('!')+'`'))
    if style=='name-only':text=''.join(n+'\n' for n,d in entries)
    elif style=='fish':text=''.join(n+'\t'+d+'\n' for n,d in entries)
    elif style=='zsh':text=''.join(n+':'+d.replace(':','\\:')+'\n' for n,d in entries)
    else:text=''.join('linkstg:'+n+'[1]::\n    '+d+'\n\n' for n,d in entries)
    if o.get('output'):Path(o.get('output')).write_text(text)
    else:out(text)


def run_main(argv):
    global COMMAND,COLOR
    aliases=configured_aliases()
    args=list(argv);global_color=None
    i=0
    while i<len(args):
        a=args[i]
        if a=='-C' or (a.startswith('-C') and len(a)>2):
            if a=='-C':
                i+=1
                if i>=len(args):cli_error("a value is required for '-C <path>' but none was supplied",False)
                path=args[i]
            else:path=a[2:]
            try:os.chdir(path)
            except OSError:fail('cannot change directory to `%s`: No such file or directory (os error 2)'%path)
            i+=1;continue
        if a=='--color' or a.startswith('--color='):
            if a=='--color':
                i+=1
                if i>=len(args):cli_error("a value is required for '--color <when>' but none was supplied",False)
                global_color=args[i]
            else:global_color=a.split('=',1)[1]
            i+=1;continue
        break
    args=args[i:]
    if global_color not in {None,'auto','always','ansi','never'}:
        cli_error("invalid value '%s' for '--color <when>'\n  [possible values: auto, always, ansi, never]"%global_color,False)
    COLOR=global_color in {'always','ansi'} or ((global_color in {None,'auto'}) and sys.stdout.isatty() and 'NO_COLOR' not in os.environ)
    if not args:
        out(HELP['-h']);return 1
    if args[0]=='--version':
        out(VERSION+subprocess.run(['git','--version'],capture_output=True,text=True).stdout);return 0
    if args[0] in {'--help','-h'}:out(HELP[args[0]]);return 0
    if args[0]=='help':
        if len(args)==1:out(HELP['--help']);return 0
        if args[1] in {'-h','--help'}:out(HELP.get('help '+args[1],HELP['--help']));return 0
        cmd=' '.join(args[1:])
        if cmd+' --help' in HELP:out(HELP[cmd+' --help']);return 0
        if cmd in aliases:
            out(cmd+' is an alias for `'+aliases[cmd]+'`\n');return 0
        COMMAND='';cli_error("unrecognized subcommand '%s'"%args[1])
    cmd=args.pop(0)
    if cmd in {'email','completion'} and args and not args[0].startswith('-'):
        cmd+=' '+args.pop(0)
        if cmd=='completion list':
            for j,x in enumerate(args):
                if x in {'commands','aliases','commands-and-aliases'}:
                    cmd+=' '+x;args=args[:j]+args[j+1:];break
    COMMAND=cmd
    if cmd in aliases and cmd not in COMMANDS:
        expansion=aliases[cmd]
        if expansion.startswith('!') or cmd in ALIASES:
            g=Git();env=os.environ.copy();env['GIT_PREFIX']=g.prefix+('/' if g.prefix else '')
            p=subprocess.run(expansion.lstrip('!')+' "$@"',shell=True,executable='/bin/sh',cwd=g.root,env=env,args=None) if False else None
            command=expansion.lstrip('!')+' '+ ' '.join(shlex.quote(a) for a in args)
            return subprocess.run(command,shell=True,cwd=g.root,env=env).returncode
        return run_main(shlex.split(expansion)+args)
    if cmd+' -h' not in HELP and cmd not in COMMANDS:
        COMMAND=''
        text="unrecognized subcommand '%s'"%cmd
        if cmd.startswith('-'):cli_error("unexpected argument '%s' found"%cmd)
        candidates=difflib.get_close_matches(cmd,COMMANDS+list(aliases),n=1,cutoff=.6)
        if candidates:text+="\n\n  tip: a similar subcommand exists: '%s'"%candidates[0]
        cli_error(text)
    # Help is intentionally available before repository discovery and validation.
    if '--help' in args or '-h' in args:
        flag='--help' if '--help' in args else '-h'
        out(HELP.get(cmd+' '+flag,HELP['--help']));return 0
    o=Options(cmd,args)
    if o.get('color'):
        COLOR=o.get('color') in {'always','ansi'} or (o.get('color')=='auto' and sys.stdout.isatty() and 'NO_COLOR' not in os.environ)
    if cmd=='version':
        out('stg 2.5.5\n' if o.get('short') else VERSION+subprocess.run(['git','--version'],capture_output=True,text=True).stdout);return 0
    if cmd.startswith('completion'):
        command_completion(cmd,o,aliases);return 0
    if cmd=='email':required('<COMMAND>')
    g=Git()
    if cmd=='branch':command_branch(g,o);return 0
    need=cmd in {'name','log','undo','redo','repair','reset'}
    s=Stack(g,o.get('branch'),required=need)
    if cmd=='init':
        if s.oldref:fail('StGit stack already initialized for branch `%s`'%s.branch)
        s.ensure()
    elif cmd=='new':command_new(s,o)
    elif cmd=='refresh':command_refresh(s,o)
    elif cmd=='edit':command_edit(s,o)
    elif cmd=='series':command_series(s,o)
    elif cmd in {'id','name'}:command_id_name(s,o,cmd=='name')
    elif cmd=='top':out(s.top()+'\n')
    elif cmd=='prev':
        s.top()
        if len(s.applied)<2:fail('not enough patches applied')
        out(s.applied[-2]+'\n')
    elif cmd=='next':
        if not s.unapplied:fail('no unapplied patches')
        out(s.unapplied[0]+'\n')
    elif cmd in {'push','pop'}:command_push_pop(s,o,cmd=='push')
    elif cmd in {'hide','unhide'}:command_hide(s,o,cmd=='unhide')
    elif cmd in {'delete','clean'}:command_delete_clean(s,o,cmd=='clean')
    elif cmd=='rename':command_rename(s,o)
    elif cmd=='goto':command_goto(s,o)
    elif cmd in {'float','sink'}:command_float_sink(s,o,cmd=='sink')
    elif cmd=='files':command_files(s,o)
    elif cmd=='diff':command_diff(s,o)
    elif cmd=='show':command_show(s,o)
    elif cmd=='patches':command_patches(s,o)
    elif cmd=='log':command_log(s,o)
    elif cmd=='commit':command_commit(s,o)
    elif cmd=='uncommit':command_uncommit(s,o)
    elif cmd=='spill':command_spill(s,o)
    elif cmd in {'undo','redo'}:command_undo_redo(s,o,cmd=='redo')
    elif cmd=='reset':command_reset(s,o)
    elif cmd=='repair':command_repair(s,o)
    elif cmd=='squash':command_squash(s,o)
    elif cmd=='pick':command_pick(s,o)
    elif cmd=='export':command_export(s,o)
    elif cmd=='import':command_import(s,o)
    elif cmd=='fold':command_fold(s,o)
    elif cmd=='rebase':command_rebase(s,o)
    elif cmd=='pull':command_pull(s,o)
    elif cmd=='email format':command_email_format(s,o)
    elif cmd=='email send':fail('could not execute `git send-email`')
    elif cmd=='sync':
        if not o.get('ref-branch') and not o.get('series'):required('--ref-branch <branch>|--series <series>')
        s.top();s.check_head();s.g.check_clean();final_top(s)
    return 0


def main():
    try:
        return run_main(sys.argv[1:])
    except StgError as e:
        if e.text:
            if e.formatted:err(e.text)
            elif COLOR:err('\x1b[1m\x1b[31merror:\x1b[0m '+e.text+'\n')
            else:err('error: '+e.text+'\n')
        return e.code
    except BrokenPipeError:
        return 0
    except KeyboardInterrupt:
        return 130
    except OSError as e:
        err('error: '+('No such file or directory (os error 2)' if e.errno==2 else str(e))+'\n')
        return 2

if __name__=='__main__':
    sys.exit(main())
