def command_pick(s,o):
    s.check_head();s.ensure()
    source=Stack(s.g,o.get('ref-branch')) if o.get('ref-branch') else s
    picks=[]
    for expr in o.pos:
        if '..' in expr:
            try:picks.extend((source.patches[n],n) for n in source.ranges([expr]))
            except StgError:
                p=s.g.run('rev-list','--reverse',expr,check=False)
                if p.returncode:raise
                picks.extend((oid,None) for oid in p.stdout.splitlines())
        else:
            oid=source.resolve(expr)
            name=next((n for n in source.all() if source.patches[n]==oid),None)
            picks.append((oid,name))
    if not o.get('noapply'):s.g.check_clean()
    for oid,pname in picks:
        c=s.g.commit(oid)
        if not c['parents']:fail('commit `%s` does not have a parent'%oid)
        if o.get('fold') or o.get('update'):
            n=s.top();g=s.g
            diff=g.raw('diff','--binary',c['parents'][0],oid,'--',*(o.get('file',[])))
            if o.get('update'):
                top=g.commit(s.patches[n]);paths=g.changed_files(top['parents'][0],top['oid'])
                diff=g.raw('diff','--binary',c['parents'][0],oid,'--',*paths)
            args=['apply','--index','--3way']+(['-R'] if o.get('revert') else [])
            g.run(*args,input=diff,cwd=g.root)
            continue
        name=o.get('name') or pname or s.make_name(c['message'])
        if name in s.patches:
            if o.get('name'):fail('patch `%s` already exists'%name)
            base_name=name;i=1
            while name in s.patches:name=base_name+'-'+str(i);i+=1
        msg=c['message'];parent=c['parents'][0];tree=c['tree'];author=c['author']
        if o.get('revert'):
            parent=oid;tree=s.g.tree(c['parents'][0]);msg='Revert "'+c['subject']+'"\n\nThis reverts commit '+oid+'.\n';author=s.g.identity('author')+' '+signature_time()
        if o.get('parent'):parent=source.resolve(o.get('parent'))
        if o.get('expose'):
            fmt=s.g.config('stgit.pick.expose-format','format:%B%n(imported from commit %H)')
            msg=s.g.raw('show','-s','--pretty='+fmt,oid).rstrip()+'\n'
        if msg!=c['message'] or parent!=c['parents'][0] or tree!=c['tree']:
            stamp=' '.join(author.rsplit(' ',2)[-2:]) if o.get('committer-date-is-author-date') else signature_time()
            picked=s.g.make_commit(tree,[parent],msg,author,s.g.identity()+' '+stamp)
        else:picked=oid
        s.patches[name]=picked;s.unapplied.insert(0,name);status('-',name)
        if not o.get('noapply'):push_one(s,name,o,True)
        else:final_top(s)
        s.save('pick '+name)


def export_text(s,n,o):
    g=s.g;c=g.commit(s.patches[n]);parent=c['parents'][0]
    diff=g.raw('diff','--binary',*extra_diff_options(o),parent,c['oid'])
    stat=g.raw('apply','--stat','--summary',input=diff,check=False) if diff else ''
    author=c['author'].rsplit(' ',2)[0]
    desc=c['message'].strip('\n')
    short,_,long=desc.partition('\n')
    long=long.lstrip('\n')
    tmpl=o.get('template')
    if not tmpl:
        for p in [os.path.join(g.dir,'patchexport.tmpl'),os.path.expanduser('~/.stgit/templates/patchexport.tmpl')]:
            if os.path.isfile(p):tmpl=p;break
    if tmpl:
        try:text=Path(tmpl).read_text()
        except OSError:fail('No such file or directory (os error 2)')
        an,ae=re.match(r'(.*) <(.*)>',author).groups()
        cn,ce=re.match(r'(.*) <(.*)>',c['committer'].rsplit(' ',2)[0]).groups()
        vals={'description':desc,'shortdescr':short,'longdescr':long,'diffstat':stat.rstrip('\n'),'authname':an,'authemail':ae,'authdate':display_date(' '.join(c['author'].rsplit(' ',2)[-2:])),'commname':cn,'commemail':ce}
        try:text=text%vals
        except Exception as e:fail('invalid export template: '+str(e))
        return text+diff
    text=short+'\n\nFrom: '+author+'\n\n'
    if long:text+=long+'\n'
    text+='---\n'+stat+'\n'+diff
    return text


def command_export(s,o):
    selected=s.ranges(o.pos,'visible') if o.pos else s.applied[:]
    if not selected:fail('no patches applied')
    if o.get('stdout'):
        for n in selected:
            if len(selected)>1:out('-'*79+'\n'+n+'\n'+'-'*79+'\n')
            out(export_text(s,n,o))
        return
    dest=o.get('dir','patches-'+s.branch)
    try:os.makedirs(dest,exist_ok=True)
    except OSError as e:fail(str(e))
    ext=o.get('extension') or ('patch' if o.get('patch') else '')
    width=max(2,len(str(len(selected))))
    lines=[]
    for i,n in enumerate(selected,1):
        filename=(str(i).zfill(width)+'-' if o.get('numbered') else '')+n+('.'+ext if ext else '')
        Path(dest,filename).write_text(export_text(s,n,o),errors='surrogateescape');lines.append(filename)
    base=s.g.commit(s.patches[selected[0]])['parents'][0]
    Path(dest,'series').write_text('# This series applies on Git commit '+base+'\n'+'\n'.join(lines)+'\n')


def split_patch_data(g,data,is_mail=False):
    meta={}
    if is_mail or re.match(r'^(From [0-9a-f]+ |From:|Subject:|Date:)',data):
        with tempfile.TemporaryDirectory(prefix='stg-mail-',dir=g.dir) as d:
            msgf=os.path.join(d,'msg');patchf=os.path.join(d,'patch')
            p=g.run('mailinfo',msgf,patchf,input=data,check=False)
            if not p.returncode:
                for line in p.stdout.splitlines():
                    k,_,v=line.partition(': ');meta[k.lower()]=v
                msg=Path(msgf).read_text(errors='surrogateescape')
                diff=Path(patchf).read_text(errors='surrogateescape')
                subj=meta.get('subject','')
                return subj+('\n\n'+msg if msg.strip() else '\n'),diff,meta
    lines=data.splitlines(True);start=None
    for i,line in enumerate(lines):
        if line.startswith('diff --git ') or (line.startswith('--- ') and i+1<len(lines) and lines[i+1].startswith('+++ ')):
            start=i;break
    if start is None:
        return data,'',meta
    header=''.join(lines[:start]);diff=''.join(lines[start:])
    if '\n---\n' in header:header=header.split('\n---\n',1)[0]
    result=[]
    for line in header.splitlines():
        if line.startswith('From: '):
            m=re.match(r'(.*) <(.*)>',line[6:])
            if m:meta['author'],meta['email']=m.groups()
        elif line.startswith('Date: '):meta['date']=line[6:]
        elif line.startswith('Subject: '):result.append(re.sub(r'^\[PATCH[^]]*\]\s*','',line[9:]))
        else:result.append(line)
    msg='\n'.join(result).strip('\n')
    msg=re.sub(r'\n{3,}','\n\n',msg)
    return msg+'\n',diff,meta


def command_import(s,o):
    s.check_head();s.ensure();s.g.check_clean()
    source=o.pos[0] if o.pos else '-'
    items=[]
    if o.get('series'):
        try:
            text=sys.stdin.read() if source=='-' else Path(source).read_text()
        except OSError:fail('No such file or directory (os error 2)')
        directory=os.path.dirname(source) if source!='-' else '.'
        for line in text.splitlines():
            val=line.split('#',1)[0].strip()
            if val:items.append((os.path.join(directory,val),None))
    elif o.get('mbox'):
        try:text=sys.stdin.read() if source=='-' else Path(source).read_text(errors='surrogateescape')
        except OSError:fail('No such file or directory (os error 2)')
        parts=re.split(r'(?m)^(?=From [0-9a-f]{40} )',text)
        items=[('-',x) for x in parts if x.strip()]
    elif o.get('mail') and os.path.isdir(source):
        items=[(os.path.join(source,n),None) for n in sorted(os.listdir(source)) if os.path.isfile(os.path.join(source,n))]
    else:items=[(source,None)]
    for path,data in items:
        if data is None:
            try:data=sys.stdin.read() if path=='-' else Path(path).read_text(errors='surrogateescape')
            except OSError:fail('No such file or directory (os error 2)')
        msg,diff,meta=split_patch_data(s.g,data,o.get('mail') or o.get('mbox'))
        name=o.get('name')
        if not name:
            if path=='-' or o.get('mail') or o.get('mbox'):name=s.make_name(msg)
            else:name=os.path.basename(path)
            if o.get('stripname'):
                name=re.sub(r'^\d+[-_.]*','',name);name=re.sub(r'\.(patch|diff)$','',name)
        name=validate_name(name,'--name <name>')
        if name in s.patches:
            if o.get('ignore') and name in s.applied:continue
            if o.get('replace') and name in s.unapplied:
                s.unapplied.remove(name);del s.patches[name]
            else:fail('patch `%s` already exists'%name)
        savedval=deepcopy(o.val)
        if meta.get('author') and not o.get('author') and not o.get('authname'):o.val['authname']=meta['author']
        if meta.get('email') and not o.get('author') and not o.get('authemail'):o.val['authemail']=meta['email']
        if meta.get('date') and not o.get('authdate'):
            try:o.val['authdate']=parse_date(meta['date'])
            except StgError:pass
        msg,author,name=prepare_message(s,o,name,default=msg)
        o.val=savedval
        base=s.topid()
        if diff:
            args=['apply','--index','-p'+str(o.get('strip',1))]
            if o.get('3way'):args.append('--3way')
            if o.get('reject'):args.append('--reject')
            if o.get('directory'):args.append('--directory='+o.get('directory'))
            if o.get('C') is not None:args+=['-C'+str(o.get('C'))]
            p=s.g.run(*args,input=diff,check=False,cwd=s.g.root)
            if p.returncode:
                err(p.stderr)
                fail('patch does not apply cleanly')
        tree=s.g.text('write-tree')
        stamp=' '.join(author.rsplit(' ',2)[-2:]) if o.get('committer-date-is-author-date') else signature_time()
        oid=s.g.make_commit(tree,[base],msg,author,s.g.identity()+' '+stamp)
        s.patches[name]=oid;s.applied.append(name);set_head(s,oid)
        status('>',name,' (new)');s.save('import '+name)


def command_fold(s,o):
    s.top();s.check_head()
    path=o.pos[0] if o.pos else '-'
    try:data=sys.stdin.read() if path=='-' else Path(path).read_text(errors='surrogateescape')
    except OSError:fail('No such file or directory (os error 2)')
    args=['apply','--index','-p'+str(o.get('strip',1))]
    if o.get('threeway'):args.append('--3way')
    if o.get('reject'):args.append('--reject')
