def command_rebase(s,o):
    s.check_head()
    g=s.g
    if o.pos:newbase=s.resolve(o.pos[0])
    else:
        ref=g.config('branch.'+s.branch+'.stgit.parentbranch')
        if not ref:fail('no parent branch specified')
        newbase=s.resolve(ref)
    g.check_clean();applied=s.applied[:]
    if applied:pop_to(s,0)
    set_head(s,newbase,checkout=True);s.base=newbase
    if not o.get('nopush') and applied:push_many(s,applied,o)
    s.save('rebase')


def command_pull(s,o):
    s.check_head();s.g.check_clean()
    repository=o.pos[0] if o.pos else s.g.config('branch.'+s.branch+'.remote')
    if not repository:fail('no pull source specified')
    applied=s.applied[:]
    if applied:pop_to(s,0)
    p=s.g.run('pull',repository,check=False)
    out(p.stdout);err(p.stderr)
    if p.returncode:fail('pull failed')
    s.head=s.g.rev('HEAD');s.base=s.head
    if not o.get('nopush'):push_many(s,applied,o)
    s.save('pull')


def command_email_format(s,o):
    patches=s.ranges(o.pos,'visible') if o.pos else s.applied[:] if o.get('all') else []
    if not patches:required('<patch>...')
    g=s.g;args=['format-patch']
    skip={'all','branch','color','git-opt'}
    for k,v in o.val.items():
        if k in skip:continue
        values=v if isinstance(v,list) else [v]
        for value in values:
