    commands=sorted(c for c in COMMANDS if c!='help')+['help']
    entries=[]
    if which!='aliases':
        for c in commands:
            desc=HELP.get(c+' -h','Print this message or the help of the given subcommand(s)').splitlines()[0]
            entries.append((c,desc))
    if which!='commands':
        for a,exp in sorted(aliases.items()):
            shell=not exp or exp.startswith('!') or a in ALIASES
            entries.append((a,'Alias for '+('shell command' if shell else 'StGit command')+' `'+exp.lstrip('!')+'`'))
    if style=='name-only':text=''.join(n+'\n' for n,d in entries)
    elif style=='fish':text=''.join(n+'\t'+d+'\n' for n,d in entries)
    elif style=='zsh':text=''.join(n+':'+d.replace(':','\\:')+'\n' for n,d in entries)
    else:text=''.join('linkstg:'+n+'[1]::\n    '+d+'\n\n' for n,d in entries)
